with deduped as (select *, row_number() over (partition by promo_code order by discount_pct desc, id) as rank_in_group from promotions qualify rank_in_group = 1) select date_trunc('quarter', ends_on) as quarter_start, case when discount_pct >= 0.34 then 'HIGH' else 'LOW' end as discount_pct_tier, sort_array(collect_set(promo_code)) as promo_code_list, avg(discount_pct) filter (where channel = 'partner') as partner_avg_discount_pct, round(avg(discount_pct), 2) as avg_discount_pct, avg(discount_pct) as avg_discount_pct_2 from deduped group by quarter_start, discount_pct_tier order by quarter_start desc
